/* Installed by the program (VM or generated main). */
typedef struct bb_program_ops {
    /* Find a Sub/Function by name. module NULL = any module (startup first). */
    void *(*find_proc)(const char *module, const char *name);
    /* Call it. argv may contain BB_REF entries for ByRef parameters. Missing
     * trailing optional args are filled in. *ret receives a function's value. */
    void (*call_proc)(void *proc, int argc, bb_value *argv, bb_value *ret);
    /* Find a module-level variable (e.g. a form's control variable): returns its
     * raw storage (see "Storage" in docs/runtime-api.md) and *type, or NULL. */
    void *(*find_global)(const char *module, const char *name, int *type);
} bb_program_ops;

void bb_set_program(const bb_program_ops *ops);
void *bb_find_proc(const char *module, const char *name);
void *bb_find_global(const char *module, const char *name, int *type);
/* Calls the proc; returns 0, or the error number if it raised an error that
 * was not handled inside (bb_err holds it). Never long-jumps out. */
int32_t bb_call_proc(void *proc, int argc, bb_value *argv, bb_value *ret);
/* Look up "<object>_<event>" in module and call it if present: returns 1 if
 * a handler existed. Errors inside are fatal (reported, exit 20) like VB. */
int bb_dispatch_event(const char *module, const char *object, const char *event,
                      int argc, bb_value *argv);
/* AddressOf: a native function (up to 8 uint32_t arguments, returns uint32_t) that calls
 * the procedure with Long arguments; see callback.c. */
